create index if not exists webhook_deliveries_user_created_idx on public.webhook_deliveries(user_id, created_at desc); create index if not exists webhook_deliveries_integration_created_idx on public.webhook_deliveries(integration_id, created_at desc); create index if not exists webhook_deliveries_failed_idx on public.webhook_deliveries(user_id, created_at desc) where status in ('failed','retry','error'); create index if not exists gateway_operations_user_created_idx on public.gateway_operation_logs(user_id, created_at desc);